#include <stdio.h>
#include <time.h>

long sumLoop(int n) { long s = 0; for (int i = 1; i <= n; i++) s += i; return s; }
long sumFormula(int n) { return (long)n * (n + 1) / 2; }

int main(void) {
    volatile long sink = 0;
    clock_t s1 = clock();
    for (int r = 0; r < 1000; r++) sink += sumLoop(10000);
    clock_t e1 = clock();
    clock_t s2 = clock();
    for (int r = 0; r < 1000; r++) sink += sumFormula(10000);
    clock_t e2 = clock();
    printf("sink=%ld\n", sink);
    printf("formula faster or equal=%d\n", (e2 - s2) <= (e1 - s1));
    return 0;
}

