        int sum = 0;
        for (int value : values) {
            sum += value;
        }
        return sum;
    }

    static double average(int[] values) {
        return (double) total(values) / values.length;
    }

    static int max(int[] values) {
        int best = values[0];
        for (int value : values) {
            if (value > best) {
                best = value;
            }
        }
        return best;
    }
}

