        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(1, times + 1):
                try:
                    return func(*args, **kwargs)
                except ValueError as exc:
                    last = exc
                    print("attempt %d failed" % attempt)
                    if delay_ms:
                        time.sleep_ms(delay_ms)
            raise last
        return wrapper
    return decorate


