class HashTable:
    def __init__(self, buckets=8):
        self.buckets = [None] * buckets
        self.size = 0

    def _index(self, key):
        return hash(key) % len(self.buckets)

    def put(self, key, value):
        i = self._index(key)
        if self.buckets[i] is None:
            self.buckets[i] = []
        chain = self.buckets[i]
        for pair in chain:
            if pair[0] == key:
                pair[1] = value
                return
        chain.append([key, value])
        self.size += 1

    def get(self, key, default=None):
        i = self._index(key)
        chain = self.buckets[i]
        if chain is not None:
            for k, v in chain:
                if k == key:
                    return v
        return default

    def delete(self, key):
        i = self._index(key)
        chain = self.buckets[i]
        if chain is None:
            return False
        for idx in range(len(chain)):
            if chain[idx][0] == key:
                chain.pop(idx)
                self.size -= 1
                return True
        return False


