def build_graph(edges):
    graph = {}
    for a, b in edges:
        if a not in graph:
            graph[a] = []
        if b not in graph:
            graph[b] = []
        graph[a].append(b)
        graph[b].append(a)
    return graph


def dfs(graph, start):
    visited = set()
    order = []
    stack = [start]
    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        order.append(node)
        for nb in sorted(graph[node], reverse=True):
            if nb not in visited:
                stack.append(nb)
    return order


def bfs(graph, start):
    import collections
    visited = {start}
    dist = {start: 0}
    q = collections.deque((start,), 100)
    while q:
        node = q.popleft()
        for nb in sorted(graph[node]):
            if nb not in visited:
                visited.add(nb)
                dist[nb] = dist[node] + 1
                q.append(nb)
    return dist


