def title_case(text):
    """把每个单词首字母大写。"""
    return " ".join(w[:1].upper() + w[1:].lower() for w in text.split())


def slugify(text):
    """转成小写连字符串，合并连续分隔符并去掉首尾。"""
    safe = []
    for ch in text.lower():
        if ch.isalpha() or ch.isdigit():
            safe.append(ch)
        else:
            safe.append("-")
    joined = "".join(safe)
    while "--" in joined:
        joined = joined.replace("--", "-")
    return joined.strip("-")


