        self.current = "hall"
        self.bag = []
        self.done = False

    def handle(self, command):
        parts = command.split()
        verb = parts[0]
        room = self.rooms[self.current]
        if verb == "look":
            return "%s: %s" % (room["desc"], ",".join(room["items"]) or "empty")
        if verb == "take" and len(parts) == 2:
            item = parts[1]
            if item in room["items"]:
                room["items"].remove(item)
                self.bag.append(item)
                return "took " + item
            return "no " + item
        if verb == "go" and len(parts) == 2:
            direction = parts[1]
            target = room["exits"].get(direction)
            if target is None:
                return "blocked"
            if target == "vault" and "key" not in self.bag:
                return "locked"
            self.current = target
            return "moved to " + target
        if verb == "win":
            if self.current == "vault" and "gold" in self.bag:
                self.done = True
                return "YOU WIN"
            return "not yet"
        return "unknown"


script = ["look", "take key", "go north", "take book", "go east",
          "take gold", "win"]
game = Game()
for cmd in script:
    print("%s -> %s" % (cmd, game.handle(cmd)))
print("bag:", game.bag)
print("won:", game.done)

def zeros(rows, cols):
    return [[0] * cols for _ in range(rows)]


def transpose(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    result = zeros(cols, rows)
    for i in range(rows):
        for j in range(cols):
            result[j][i] = matrix[i][j]
    return result


def matmul(a, b):
    n, m = len(a), len(a[0])
    m2, p = len(b), len(b[0])
    if m != m2:
        raise ValueError("shape %dx%d vs %dx%d" % (n, m, m2, p))
    result = zeros(n, p)
    for i in range(n):
        for j in range(p):
            total = 0
            for k in range(m):
                total += a[i][k] * b[k][j]
            result[i][j] = total
    return result


def det2(matrix):
    return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]


a = [[1, 2], [3, 4]]
b = [[5, 6], [7, 8]]
print("transpose:", transpose(a))
print("product:", matmul(a, b))
print("identity:", matmul(a, [[1, 0], [0, 1]]))
print("det a:", det2(a))
try:
    matmul([[1, 2, 3]], [[1, 2]])
except ValueError as e:
    print("error:", e)

